-- The expenses template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "expenses" (
  "id" text primary key default gen_random_uuid()::text,
  "what" text,
  "amount" double precision,
  "budget_id" text,
  "status" text,
  "date" date,
  "spent_by" text,
  "receipt" jsonb,
  "approver" text,
  "approved_on" date
);
create table "budgets" (
  "id" text primary key default gen_random_uuid()::text,
  "category" text,
  "monthly" double precision
);

comment on column "expenses"."what" is 'svgrid:{"field":"what","header":"Expense","width":240,"fieldType":"text"}';
comment on column "expenses"."amount" is 'svgrid:{"field":"amount","header":"Amount","width":120,"fieldType":"number","fieldProps":{"format":"currency","symbol":"$","precision":2,"summary":"sum"}}';
comment on column "expenses"."budget_id" is 'svgrid:{"field":"budget","header":"Category","width":140,"fieldType":"link","fieldProps":{"table":"budgets","multiple":false,"inverse":"expenses"}}';
comment on column "expenses"."status" is 'svgrid:{"field":"status","header":"Status","width":150,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Draft","color":"#94a3b8"},{"value":"Submitted","color":"#18bfff"},{"value":"Needs approval","color":"#fcb400"},{"value":"Approved","color":"#20c933"},{"value":"Rejected","color":"#f82b60"},{"value":"Paid","color":"#2d7ff9"}]}}';
comment on column "expenses"."date" is 'svgrid:{"field":"date","header":"Date","width":150,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "expenses"."spent_by" is 'svgrid:{"field":"spentBy","header":"Spent by","width":160,"fieldType":"user"}';
comment on column "expenses"."receipt" is 'svgrid:{"field":"receipt","header":"Receipt","width":100,"fieldType":"attachment","fieldProps":{"accept":"image/*,application/pdf","maxFiles":3}}';
comment on column "expenses"."approver" is 'svgrid:{"field":"approver","header":"Approved by","width":160,"fieldType":"user"}';
comment on column "expenses"."approved_on" is 'svgrid:{"field":"approvedOn","header":"Approved on","width":150,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
