comment on table "budgets" is 'svgrid:{"v":1,"name":"Budgets","position":1,"primaryField":"category","order":["category","monthly","expenses","spent","left"],"extra":[{"field":"expenses","header":"Expenses","width":320,"fieldType":"link","fieldProps":{"table":"expenses","multiple":true,"inverse":"budget"}},{"field":"spent","header":"Spent","width":130,"fieldType":"rollup","fieldProps":{"linkField":"expenses","field":"amount","aggregation":"SUM"}},{"field":"left","header":"Left","width":130,"fieldType":"formula","fieldProps":{"formula":"{Monthly budget} - {Spent}","result":"currency","precision":0}}],"views":[{"id":"all","name":"All categories","type":"grid"}],"automations":[{"id":"over","name":"Over budget","enabled":true,"trigger":{"type":"recordMatches"},"condition":{"kind":"fieldFilter","conjunction":"and","conditions":[{"column":"left","kind":"number","op":"lt","value":0}]},"actions":[{"type":"highlight","fields":["left"],"background":"#fee2e2","color":"#991b1b"},{"type":"notify","message":"{Category} is over budget: {Left}","severity":"error"}]}]}';

